+// Send sends to an ServerIdentity without wrapping the msg into a SDAMessage
+func (t *TCPRouter) Send(e *network.ServerIdentity, msg network.Body) error {
+	if msg == nil {
+		return errors.New("Can't send nil-packet")
+	}
+	t.networkLock.RLock()
+	c, ok := t.connections[e.ID]
+	t.networkLock.RUnlock()
+	if !ok {
+		var err error
+		c, err = t.Connect(e)
+		if err != nil {
+			return err
+		}
+	}
+
+	log.Lvlf4("%s sends to %s msg: %+v", t.serverIdentity.Addresses, e, msg)
+	var err error
+	err = c.Send(context.TODO(), msg)
+	if err != nil /*&& err != network.ErrClosed*/ {
+		log.Lvl2("Couldn't send to", c.ServerIdentity().First(), ":", err, "trying again")
+		c, err = t.Connect(e)
+		if err != nil {
+			return err
+		}
+		err = c.Send(context.TODO(), msg)
+		if err != nil {
+			return err
+		}
+	}
+	log.Lvl5("Message sent")
+	return nil
+}

File: network/encoding.go  Lines: 267-282
// NewNetworkMessage takes a ProtocolMessage and then constructs a
// Message from it. Error if the type is unknown
func NewNetworkMessage(obj Body) (*Packet, error) {
	val := reflect.ValueOf(obj)
	if val.Kind() != reflect.Ptr {
		return nil, fmt.Errorf("Send takes a pointer to the message, not a copy...")
	}
	ty := TypeFromData(obj)
	if ty == ErrorType {
		return &Packet{}, fmt.Errorf("Packet to send is not known. Please register packet: %s\n",
			reflect.TypeOf(obj).String())
	}
	return &Packet{
		MsgType: ty,
		Msg:     obj}, nil
}

