	w := &workerServer{
		requests:  make(chan *Request),
		responses: map[string]chan *Response{},
		process:   cmd,
		stderr:    stderr,
		state:     state,
	}
	workerMap[worker] = w
	go w.sendRequests(stdin)
	go w.readResponses(stdout)
	go w.wait()
	state.Stats.NumWorkerProcesses = len(workerMap)
	return w, nil
}

