func checkResourceType(t string) (string, error) {
	for _, resourceType := range resourceTypes {
		if resourceType.name == t {
			return t, nil
		}
	}
	return "", stdcli.Errorf("unsupported resource type %s; see 'convox resources create --help'", t)
}

