 func (o outbound) Call(ctx context.Context, req *transport.Request) (*transport.Response, error) {
+	start := time.Now()
+	if req.TTL != 0 {
+		var cancel func()
+		ctx, cancel = context.WithDeadline(ctx, start.Add(req.TTL))
+		defer cancel()
+	}
