// NewAccount creates a new in memory Account with userName assigned to
// authMethodId. Name and description are the only valid options. All other
// options are ignored.
func NewAccount(authMethodId string, userName string, opt ...Option) (*Account, error) {
	// NOTE(mgaffney): The scopeId in the embedded *store.Account is
	// populated by a trigger in the database.
	if authMethodId == "" {
		return nil, fmt.Errorf("new: password account: no auth method id: %w", db.ErrInvalidParameter)
	}
	if userName == "" {
		return nil, fmt.Errorf("new: password account: no user name: %w", db.ErrInvalidParameter)
	}

	opts := getOpts(opt...)
	a := &Account{
		Account: &store.Account{
			AuthMethodId: authMethodId,
			UserName:     userName,
			Name:         opts.withName,
			Description:  opts.withDescription,
		},
	}
	return a, nil
}

File: internal/auth/password/repository_account.go  Lines: 135-165
// DeleteAccount deletes the account for the provided id from the repository returning a count of the
// number of records deleted.  All options are ignored.
func (r *Repository) DeleteAccount(ctx context.Context, withPublicId string, opt ...Option) (int, error) {
	if withPublicId == "" {
		return db.NoRowsAffected, fmt.Errorf("delete: password account: missing public id: %w", db.ErrInvalidParameter)
	}
	ac := allocAccount()
	ac.PublicId = withPublicId

	var rowsDeleted int
	_, err := r.writer.DoTx(
		ctx,
		db.StdRetryCnt,
		db.ExpBackoff{},
		func(_ db.Reader, w db.Writer) (err error) {
			metadata := ac.oplog(oplog.OpType_OP_TYPE_DELETE)
			dAc := ac.clone()
			rowsDeleted, err = w.Delete(ctx, dAc, db.WithOplog(r.wrapper, metadata))
			if err == nil && rowsDeleted > 1 {
				return db.ErrMultipleRecords
			}
			return err
		},
	)

	if err != nil {
		return db.NoRowsAffected, fmt.Errorf("delete: password account: %s: %w", withPublicId, err)
	}

	return rowsDeleted, nil
}

