}

File: graphql2/graphqlapp/contactmethod.go  Lines: 21-33
func (a *ContactMethod) FormattedValue(ctx context.Context, obj *contactmethod.ContactMethod) (string, error) {
	formatted := obj.Value
	switch obj.Type {
	case contactmethod.TypeSMS, contactmethod.TypeVoice:
		num, err := libphonenumber.Parse(obj.Value, "")
		if err != nil {
			log.Log(ctx, err)
			break
		}
		formatted = libphonenumber.Format(num, libphonenumber.INTERNATIONAL)
	}
	return formatted, nil
}

File: user/contactmethod/store.go  Lines: 104-121
func (db *DB) DisableByValue(ctx context.Context, t Type, v string) error {
	c := ContactMethod{Name: "Disable", Type: t, Value: v}
	n, err := c.Normalize()
	if err != nil {
		return err
	}
	err = permission.LimitCheckAny(ctx, permission.System)
	if err != nil {
		return err
	}
	switch t {
	case TypeSMS, TypeVoice:
		_, err = db.disablePhone.ExecContext(ctx, n.Value)
	default:
		_, err = db.disable.ExecContext(ctx, n.Type, n.Value)
	}
	return err
}

