func GetProcess(app, id string) (*Process, error) {
	// Find ECS Task
	processes, err := ListProcesses(app)

	if err != nil {
		return nil, err
	}

	for _, p := range processes {
		if p.Id == id {
			return p, nil
		}
	}

	// Find one-off Docker process
	oneoff, err := ListOneoffProcesses(app)

	if err != nil {
		return nil, err
	}

	for _, p := range oneoff {
		if p.Id == id {
			return p, nil
		}
	}

	return nil, nil
}

