+func (m *bpfEndpointManager) attachXDPProgram(ifaceName string, ep *proto.HostEndpoint) error {
+	ap := xdp.AttachPoint{
+		Iface:    ifaceName,
+		LogLevel: m.bpfLogLevel,
+		Modes:    m.xdpModes,
+	}
+
+	jumpMapFD, err := m.dp.ensureProgramAttached(&ap)
+	if err != nil {
