+func (fnb *FlowNodeBuilder) EnqueueAdminServerInit(ctx context.Context) {
+	fnb.Component("admin server", func(builder NodeBuilder, node *NodeConfig) (module.ReadyDoneAware, error) {
+		var opts []admin.CommandRunnerOption
