+// MergeSpendAction merge common assetID and accountID spend action
+func MergeSpendAction(spendActions []txbuilder.Action) []txbuilder.Action {
+	actions := []txbuilder.Action{}
+	actionMap := make(map[string]*spendAction)
+
+	for _, act := range spendActions {
+		switch act := act.(type) {
+		case *spendAction:
+			actionKey := act.AssetId.String() + act.AccountID
+			if tmpAct, ok := actionMap[actionKey]; ok {
+				tmpAct.Amount += act.Amount
+			} else {
+				actionMap[actionKey] = act
+			}
+		default:
+			continue
+		}
+	}
+
+	for actKey := range actionMap {
+		spend := actionMap[actKey]
+		actions = append(actions, txbuilder.Action(spend))
+	}
+
+	return actions
+}

File: api/transact.go  Lines: 52-93
// TODO modify mergeActions to loadSpendAction
func mergeActions(req *BuildRequest) ([]map[string]interface{}, error) {
	var actions []map[string]interface{}
	actionMap := make(map[string]map[string]interface{})

	for _, m := range req.Actions {
		if actionType := m["type"].(string); actionType != "spend_account" {
			actions = append(actions, m)
			continue
		}

		if m["amount"] == nil {
			return nil, errEmptyAmount
		}

		amountNumber := m["amount"].(json.Number)
		amount, err := amountNumber.Int64()
		if err != nil || amount == 0 {
			return nil, errBadAmount
		}

		actionKey := m["asset_id"].(string) + m["account_id"].(string)
		if tmpM, ok := actionMap[actionKey]; ok {
			if tmpM["amount"] == nil {
				return nil, errEmptyAmount
			}

			tmpNumber := tmpM["amount"].(json.Number)
			tmpAmount, err := tmpNumber.Int64()
			if err != nil || tmpAmount == 0 {
				return nil, errBadAmount
			}

			tmpM["amount"] = json.Number(fmt.Sprintf("%v", tmpAmount+amount))
		} else {
			actionMap[actionKey] = m
			actions = append(actions, m)
		}
	}

	return actions, nil
}

