	for rows.Next() {
		err = rows.Scan(
			&rot.ID,
			&rot.Type,
			&rot.Start,
			&rot.ShiftLength,
			&tzName,
			&state.ShiftStart,
			&state.Position,
			&partCount,
		)
		if err != nil {
			return nil, errors.Wrap(err, "scan rotation data")
		}
		loc, err = util.LoadLocation(tzName)
		if err != nil {
@@ -114,7 +115,7 @@
