+func (bft *ProtocolBFTCoSi) handleResponseCommit(r *Response) error {
+	// check if we have enough
+	// FIXME possible data race
+	bft.tcrMut.Lock()
+	defer bft.tcrMut.Unlock()
+	bft.tempCommitResponse = append(bft.tempCommitResponse, r.Response)
+
