	}, reqBuf)

	require.Equal(t, errors.New("bar"), err)

	var response simpleResponse
	require.NoError(t, json.Unmarshal(resBuf.Bytes(), &response))
	assert.Equal(t, simpleResponse{Success: true}, response)
}

