+		if err != nil {
+			return errors.New("Failed to write database")
+		}
+	}
+
+	err = dbData.Rsw.SetWorkingHash(ctx, workingHash)
+	if err != nil {
+		return err
+	}
+
+	err = dbData.Rsw.SetStagedHash(ctx, stagedHash)
+	if err != nil {
+		return err
+	}
