package legacy

import (
	"github.com/bytom/crypto/sha3pool"
	"github.com/bytom/protocol/bc"
	"github.com/bytom/protocol/vm"
	"github.com/bytom/protocol/vm/vmutil"
)

// MapTx converts a legacy TxData object into its entries-based
// representation.
func MapTx(oldTx *TxData) *bc.Tx {
	txid, header, entries := mapTx(oldTx)

	tx := &bc.Tx{
		TxHeader: header,
		ID:       txid,
		Entries:  entries,
		InputIDs: make([]bc.Hash, len(oldTx.Inputs)),
	}

	var (
		nonceIDs       = make(map[bc.Hash]bool)
		spentOutputIDs = make(map[bc.Hash]bool)
	)
	for id, e := range entries {
		var ord uint64
		switch e := e.(type) {
		case *bc.Issuance:
			anchor, ok := entries[*e.AnchorId]
			if !ok {
				// this tx will be invalid because this issuance is
				// missing an anchor
				continue
			}
			if _, ok := anchor.(*bc.Nonce); ok {
				nonceIDs[*e.AnchorId] = true
			}
			ord = e.Ordinal
			// resume below after the switch

		case *bc.Spend:
			spentOutputIDs[*e.SpentOutputId] = true
			ord = e.Ordinal
			// resume below after the switch

		default:
			continue
		}
		if ord >= uint64(len(oldTx.Inputs)) {
			continue // poorly-formed transaction
		}
		tx.InputIDs[ord] = id
	}

	for id := range nonceIDs {
		tx.NonceIDs = append(tx.NonceIDs, id)
	}
	for id := range spentOutputIDs {
		tx.SpentOutputIDs = append(tx.SpentOutputIDs, id)
	}
	return tx
}

File: mining/mining.go  Lines: 28-54
func createCoinbaseTx(accountManager *account.Manager, amount uint64, blockHeight uint64) (tx *legacy.Tx, err error) {
	amount += consensus.BlockSubsidy(blockHeight)
	unlockHeight := blockHeight + consensus.CoinbasePendingBlockNumber

	var script []byte
	if accountManager == nil {
		script, err = vmutil.CoinbaseProgram(nil, 0, unlockHeight)
	} else {
		script, err = accountManager.GetCoinbaseControlProgram(unlockHeight)
	}
	if err != nil {
		return
	}

	builder := txbuilder.NewBuilder(time.Now())
	builder.AddOutput(legacy.NewTxOutput(*consensus.BTMAssetID, amount, script, nil))
	_, txData, err := builder.Build()
	if err != nil {
		return
	}

	tx = &legacy.Tx{
		TxData: *txData,
		Tx:     legacy.MapTx(txData),
	}
	return
}

