	// Register legacy gRPC handlers for backwards compatibility, to be removed at a later date
	legacyaccessproto.RegisterAccessAPIServer(
		eng.grpcServer,
		legacyaccess.NewHandler(backend, chainID.Chain()),
	)

	return eng
}

