File: go/libraries/doltcore/schema/alterschema/modifycolumn.go  Lines: 31-60
func ModifyColumn(
	ctx context.Context,
	tbl *doltdb.Table,
	existingCol schema.Column,
	newCol schema.Column,
	defaultVal types.Value,
	order *ColumnOrder,
) (*doltdb.Table, error) {

	sch, err := tbl.GetSchema(ctx)
	if err != nil {
		return nil, err
	}

	if err := validateModifyColumn(ctx, tbl, existingCol, newCol, defaultVal); err != nil {
		return nil, err
	}

	// Modify statements won't include key info, so fill it in from the old column
	if existingCol.IsPartOfPK {
		newCol.IsPartOfPK = true
	}

	newSchema, err := replaceColumnInSchema(sch, existingCol.Name, newCol, order)
	if err != nil {
		return nil, err
	}

	return updateTableWithModifiedColumn(ctx, tbl, newSchema, newCol)
}

File: go/libraries/doltcore/schema/alterschema/addcolumn.go  Lines: 110-138
// addColumnToSchema creates a new schema with a column as specified by the params.
func addColumnToSchema(sch schema.Schema, tag uint64, newColName string, typeInfo typeinfo.TypeInfo, nullable Nullable, order *ColumnOrder) (schema.Schema, error) {
	newCol, err := createColumn(nullable, newColName, tag, typeInfo)
	if err != nil {
		return nil, err
	}

	var newCols []schema.Column
	if order != nil && order.First {
		newCols = append(newCols, newCol)
	}
	sch.GetAllCols().Iter(func(tag uint64, col schema.Column) (stop bool, err error) {
		newCols = append(newCols, col)
		if order != nil && order.After == col.Name {
			newCols = append(newCols, newCol)
		}
		return false, nil
	})
	if order == nil {
		newCols = append(newCols, newCol)
	}

	collection, err := schema.NewColCollection(newCols...)
	if err != nil {
		return nil, err
	}

	return schema.SchemaFromCols(collection), nil
}

