+	ctx, cancel := context.WithCancel(context.TODO())
+	defer cancel()
+	ctrl, client, _, privateTaskEngine, _, _, _ := mocks(t, ctx, &defaultConfig)
+	defer ctrl.Finish()
+
+	taskEngine, _ := privateTaskEngine.(*DockerTaskEngine)
+
+	mockState := mock_dockerstate.NewMockTaskEngineState(ctrl)
+	taskEngine.state = mockState
+
+	testContainer := &apicontainer.Container{
+		Name: "c1",
+	}
+
+	testTask := &apitask.Task{
+		Arn:     "myTaskArn",
+		Family:  "myFamily",
+		Version: "1",
+		Containers: []*apicontainer.Container{
+			testContainer,
+		},
+	}
+
+	containerMap := map[string]*apicontainer.DockerContainer{
+		"c1": &apicontainer.DockerContainer{
+			Container:  testContainer,
+			DockerName: "d1",
+		},
+	}
+
+	client.EXPECT().APIVersion().Return(defaultDockerClientAPIVersion, nil).AnyTimes()
+	mockState.EXPECT().ContainerMapByArn("myTaskArn").Return(containerMap, true)
+	mockState.EXPECT().GenerateAndAddV3EndpointID(testTask, testContainer, gomock.Any()).Do(func(task *apitask.Task, container *apicontainer.Container, uuid uuidwrapper.UUID) {
+		container.V3EndpointID = "v3EndpointID"
+	}).Return(true)
+	client.EXPECT().CreateContainer(gomock.Any(), gomock.Any(), gomock.Any(), gomock.Any(), gomock.Any())
+	taskEngine.createContainer(testTask, testContainer)
+
+	// check that we have injected v3 endpoint into it
+	assert.NotNil(t, testContainer.Environment)
+	assert.Equal(t, testContainer.Environment[apicontainer.ContainerMetadataURIEnvironmentVariableName],
+		fmt.Sprintf(apicontainer.ContainerMetadataURIFormat, testContainer.V3EndpointID))
+}

