	rows, err := tx.StmtContext(ctx, db.escalate).QueryContext(ctx, ids64)
	if err == sql.ErrNoRows {
		log.Debugf(ctx, "escalate alert: no rows matched")
		err = nil
	}
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	updatedIDs := make([]int, 0, len(alertIDs))
	for rows.Next() {
		var id int
		err := rows.Scan(&id)
		if err != nil {
			return nil, err
		}
		updatedIDs = append(updatedIDs, id)
	}

	err = db.logDB.LogManyTx(ctx, tx, updatedIDs, alertlog.TypeEscalationRequest, nil)
	if err != nil {
		return nil, err
	}

	err = tx.Commit()
	if err != nil {
		return nil, err
	}
	return updatedIDs, err
}

