				optionMap[name] = val
			}
			optionsMap[input.Package] = optionMap
		}
		// Add in extra defined options
		if len(in.extraOptions) > 0 {
			optionMap := optionsMap[input.Package]
			if optionMap == nil {
				optionMap = map[string]fieldInfo{}
			}
			for _, val := range in.extraOptions {
