				var e *p2p.DisconnectError
				if errors.As(err, &e) {
					_ = s.Disconnect(overlay)
				}

				logger.Debugf("error handle protocol %s/%s: stream %s: peer %s: error: %v", p.Name, p.Version, ss.Name, overlay, err)
