func (o *Overlay) StartNewNode(protocolID uuid.UUID, tree *Tree) (*Node, error) {

	// instantiate node
	var err error
	var node *Node
	node, err = o.CreateNewNode(protocolID, tree)
	if err != nil {
		return nil, err
	}
	// start it
	dbg.Lvl3("Starting new node at", o.host.Entity.Addresses)
	go node.Start()
	return node, nil
}

