// setAddress parses a given string and looks for org and project info, setting
// the actual address to the base. Note that if a very malformed URL is passed
// in, this may not return what one expects. For now this is on purpose to
// avoid requiring error handling.
//
// This also removes any trailing "/v1"; we'll use that in our commands so we
// don't require it from users.
func (c *Config) setAddr(addr string) error {
	u, err := url.Parse(addr)
	if err != nil {
		return fmt.Errorf("error parsing address: %w", err)
	}
	c.Addr = fmt.Sprintf("%s://%s", u.Scheme, u.Host)

	path := strings.TrimPrefix(u.Path, "/v1")
	path = strings.TrimPrefix(path, "/")
	if path == "" {
		return nil
	}

	split := strings.Split(path, "/")
	switch len(split) {
	case 0:
	case 2:
		switch split[0] {
		case "orgs":
			c.Org = split[1]
		case "projects":
			c.Project = split[1]
		default:
			return fmt.Errorf("expected orgs or projects segment first in address, found %q", split[0])
		}
	case 4:
		if split[0] != "orgs" {
			return fmt.Errorf("expected orgs segment in address, found %q", split[0])
		}
		c.Org = split[1]
		if split[2] != "projects" {
			return fmt.Errorf("expected projects segment in address, found %q", split[2])
		}
		c.Project = split[3]
	default:
		return fmt.Errorf("unexpected number of segments in address")
	}

	return nil
}

