File: go/libraries/doltcore/sqle/database.go  Lines: 170-191
// DropTable drops the table with the name given
func (db *Database) DropTable(ctx *sql.Context, tableName string) error {
	tableExists, err := db.root.HasTable(ctx, tableName)
	if err != nil {
		return err
	}

	if !tableExists {
		return sql.ErrTableNotFound.New(tableName)
	}

	newRoot, err := db.root.RemoveTables(ctx, tableName)
	if err != nil {
		return err
	}

	delete(db.tables, tableName)

	db.SetRoot(newRoot)

	return nil
}

File: go/libraries/doltcore/sqle/database.go  Lines: 249-258
// Flushes the current batch of outstanding changes and returns any errors.
func (db *Database) Flush(ctx context.Context) error {
	for name, table := range db.tables {
		if err := table.flushBatchedEdits(ctx); err != nil {
			return err
		}
		delete(db.tables, name)
	}
	return nil
}

