+				c.recorder.Eventf(ch, corev1.EventTypeWarning, CleanUpError, "Error cleaning up challenge: %v", err)
 				ch.Status.Reason = err.Error()
 				log.Error(err, "error cleaning up challenge")
 				return err
			}

