		return
	}

	if !isListing && !canRead {
		s.handleNeedAuthenticationAndPopulateSRI(w, r, realm, sri)
		return
	}

	http.FileServer(st.getHTTPFileSystem(ctx)).ServeHTTP(w, r)
}

