File: insonmnia/miner/plugin/plugin.go  Lines: 175-223
// TuneVolumes creates volumes required for the given provider with further
// host config tuning with mount settings.
func (r *Repository) TuneVolumes(provider VolumeProvider, cfg *container.HostConfig) (Cleanup, error) {
	cleanup := newNestedCleanup()

	for volumeName, options := range provider.Volumes() {
		mounts := provider.Mounts(volumeName)
		// No mounts - no volumes.
		if len(mounts) == 0 {
			continue
		}

		driver, ok := r.volumes[options.Driver]
		if !ok {
			cleanup.Close()
			return nil, fmt.Errorf("volume driver not supported: %s", options.Driver)
		}

		id := fmt.Sprintf("%s/%s", provider.ID(), volumeName)

		v, err := driver.CreateVolume(id, options.Settings)
		if err != nil {
			cleanup.Close()
			return nil, err
		}

		for _, mount := range mounts {
			// We don't trust the provider implementation.
			if mount.Source != volumeName {
				continue
			}

			mount = volume.Mount{
				Source:     id,
				Target:     mount.Target,
				Permission: mount.Permission,
			}

			if err := v.Configure(mount, cfg); err != nil {
				cleanup.Close()
				return nil, err
			}
		}

		cleanup.Add(&volumeCleanup{driver: driver, id: id})
	}

	return &cleanup, nil
}

File: insonmnia/miner/plugin/plugin.go  Lines: 225-243
func (r *Repository) TuneNetworks(provider NetworkProvider, hostCfg *container.HostConfig, netCfg *network.NetworkingConfig) (Cleanup, error) {
	log.G(context.Background()).Info("tuning networks")
	cleanup := newNestedCleanup()
	networks := provider.Networks()
	for _, net := range networks {
		tuner, ok := r.networkTuners[net.NetworkType()]
		if !ok {
			cleanup.Close()
			return nil, fmt.Errorf("network driver not supported: %s", net.NetworkType())
		}
		c, err := tuner.Tune(net, hostCfg, netCfg)
		if err != nil {
			cleanup.Close()
			return nil, err
		}
		cleanup.Add(c)
	}
	return &cleanup, nil
}

File: insonmnia/miner/network/l2tp_tuner.go  Lines: 107-140
@@ -0,0 +107,34 @@
+func (t *L2TPTuner) Tune(net structs.Network, hostCfg *container.HostConfig, netCfg *network.NetworkingConfig) (Cleanup, error) {
+	log.G(context.Background()).Info("tuning 2ltp")
+	configPath, err := t.writeConfig(net.ID(), net.NetworkOptions())
+	if err != nil {
+		return nil, err
+	}
+
+	driverOpts := map[string]string{"config": configPath}
+	createOpts := types.NetworkCreate{
+		Driver:  "l2tp_net",
+		Options: driverOpts,
+		IPAM:    &network.IPAM{Driver: "l2tp_ipam", Options: driverOpts},
+	}
+
+	response, err := t.cli.NetworkCreate(context.Background(), net.ID(), createOpts)
+	if err != nil {
+		return nil, err
+	}
+
+	if netCfg.EndpointsConfig == nil {
+		netCfg.EndpointsConfig = make(map[string]*network.EndpointSettings)
+		netCfg.EndpointsConfig[response.ID] = &network.EndpointSettings{
+			IPAMConfig: &network.EndpointIPAMConfig{IPv4Address: net.NetworkAddr()},
+			IPAddress:  net.NetworkAddr(),
+			NetworkID:  response.ID,
+		}
+	}
+
+	return &L2TPCleaner{
+		cli:        t.cli,
+		networkID:  response.ID,
+		configPath: configPath,
+	}, nil
+}

