+// Execute displays the status of the service.
+func (o *svcStatusOpts) Execute() error {
+	err := o.initStatusDescriber(o)
+	if err != nil {
+		return err
+	}
+	svcStatus, err := o.statusDescriber.Describe()
+	if err != nil {
+		return fmt.Errorf("describe status of service %s: %w", o.svcName, err)
+	}
+	if o.shouldOutputJSON {
+		data, err := svcStatus.JSONString()
+		if err != nil {
+			return err
+		}
+		fmt.Fprintf(o.w, data)
+	} else {
+		fmt.Fprintf(o.w, svcStatus.HumanString())
+	}
+
+	return nil
+}

File: internal/pkg/cli/svc_logs.go  Lines: 137-161
// Execute outputs logs of the service.
func (o *svcLogsOpts) Execute() error {
	logGroupName := fmt.Sprintf(logGroupNamePattern, o.AppName(), o.envName, o.svcName)
	logEventsOutput := &cloudwatchlogs.LogEventsOutput{
		LastEventTime: make(map[string]int64),
	}
	var err error
	for {
		logEventsOutput, err = o.cwlogsSvc[o.envName].TaskLogEvents(logGroupName, logEventsOutput.LastEventTime, o.generateGetLogEventOpts()...)
		if err != nil {
			return err
		}
		if err := o.outputLogs(logEventsOutput.Events); err != nil {
			return err
		}
		if !o.follow {
			return nil
		}
		// for unit test.
		if logEventsOutput.LastEventTime == nil {
			return nil
		}
		time.Sleep(cloudwatchlogs.SleepDuration)
	}
}

