func (sw *Switch) addPeerWithConnection(conn net.Conn) error {
	peerConn, err := newInboundPeerConn(conn, sw.reactorsByCh, sw.chDescs, sw.StopPeerForError, sw.nodePrivKey, sw.Config)
	if err != nil {
		conn.Close()
		return err
	}
	if err = sw.AddPeer(peerConn); err != nil {
		conn.Close()
		return err
	}

	return nil
}

